(() => {
'use strict';const $=s=>document.querySelector(s),core=window.QuadraticInequality;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}const symbols={'<':'<','<=':'\\le','>':'>','>=':'\\ge'},sign=n=>n===0?'0':n>0?'+':'-';
function table(q){const host=$('#quadratic-sign-table'),t=document.createElement('table'),caption=document.createElement('caption');caption.textContent='Tanda pada setiap daerah dan pada akar';t.append(caption);let columns;if(q.factors){const roots=[...new Set(q.factors)].sort((a,b)=>a-b);columns=[];let previous=-Infinity;for(const root of roots){columns.push({tex:previous===-Infinity?`x<${root}`:`${previous}<x<${root}`,x:previous===-Infinity?root-1:(previous+root)/2});columns.push({tex:`x=${root}`,x:root});previous=root;}columns.push({tex:`x>${previous}`,x:previous+1});}else columns=[{tex:'x\\in\\mathbb R',x:0}];const thead=document.createElement('thead'),header=document.createElement('tr'),label=document.createElement('th');label.scope='col';label.textContent='Bentuk';header.append(label);for(const column of columns){const th=document.createElement('th');th.scope='col';math(th,column.tex);header.append(th);}thead.append(header);t.append(thead);const tbody=document.createElement('tbody');const rows=q.factors?[{tex:String(q.a),fn:()=>q.a},...q.factors.map(r=>({tex:r<0?`x+${-r}`:r===0?'x':`x-${r}`,fn:x=>x-r})),{tex:q.tex,fn:x=>core.value(q,x)}]:[{tex:q.tex,fn:x=>core.value(q,x)}];for(const row of rows){const tr=document.createElement('tr'),th=document.createElement('th');th.scope='row';math(th,row.tex);tr.append(th);for(const column of columns){const td=document.createElement('td');math(td,sign(row.fn(column.x)));tr.append(td);}tbody.append(tr);}t.append(tbody);host.replaceChildren(t);}
function draw(){const q=core.cases.find(q=>q.id===$('#quadratic-case').value),relation=$('#quadratic-relation').value,x=Number($('#quadratic-trial').value),v=core.value(q,x),result=core.solve(q,relation);$('#quadratic-trial-output').value=String(x).replace('.',',');math($('#quadratic-equation'),`${q.tex}${symbols[relation]}0`);math($('#quadratic-result'),`S=${core.intervalTex(result)}`);math($('#quadratic-value'),`x=${String(x).replace('.','{,}')}:\\quad f(x)=${String(v).replace('.','{,}')}`);table(q);const point=(x,y)=>[35+(x+5)*33,140-y*20];let path='';for(let i=0;i<=320;i++){const px=-5+i/32,[sx,sy]=point(px,core.value(q,px));path+=(i?'L':'M')+sx.toFixed(2)+' '+sy.toFixed(2); }$('#quadratic-curve').setAttribute('d',path);const [sx,sy]=point(x,v);$('#quadratic-trial-point').setAttribute('cx',sx);$('#quadratic-trial-point').setAttribute('cy',sy);$('#quadratic-plot').setAttribute('aria-label',`Parabola dengan koefisien utama ${q.a}. Masukan uji ${x}, keluaran ${v}. ${Math.abs(v)>6?'Titik uji di luar jendela grafik.':''}`);$('#quadratic-feedback').textContent=`Pada masukan ${String(x).replace('.',',')}, hasil kuadrat ${String(v).replace('.',',')} ${v===0?'nol':v>0?'positif':'negatif'}. ${core.accepts(q,relation,x)?'Memenuhi':'Tidak memenuhi'} pertidaksamaan yang dipilih.`+(Math.abs(v)>6?' Titik uji berada di luar jendela keluaran; gunakan nilai numeriknya.':'');}
$('#quadratic-case').addEventListener('change',draw);$('#quadratic-relation').addEventListener('change',draw);$('#quadratic-trial').addEventListener('input',draw);$('#quadratic-reset').addEventListener('click',()=>{$('#quadratic-case').value='up';$('#quadratic-relation').value='<=';$('#quadratic-trial').value=0;draw();});draw();
const questions=[
[String.raw`(x+2)(x-1)\le0`,[String.raw`[-2,1]`,String.raw`(-2,1)`,String.raw`(-\infty,-2]\cup[1,\infty)`],0,'Hasil kali negatif di antara kedua akar dan nol pada akarnya. Tanda tak ketat memasukkan kedua batas.'],
[String.raw`(x+2)(x-1)>0`,[String.raw`(-2,1)`,String.raw`(-\infty,-2)\cup(1,\infty)`,String.raw`[-2,1]`],1,'Hasil kali positif di luar kedua akar. Tanda ketat tidak memasukkan akar.'],
[String.raw`-(x+2)(x-1)<0`,[String.raw`(-2,1)`,String.raw`[-2,1]`,String.raw`(-\infty,-2)\cup(1,\infty)`],2,'Faktor negatif di depan membalik tanda hasil kali. Daerah luar kini menghasilkan nilai negatif.'],
[String.raw`(x-1)^2\le0`,[String.raw`\varnothing`,String.raw`\{1\}`,String.raw`\mathbb R`],1,'Kuadrat tidak negatif dan hanya nol pada satu. Jadi hanya satu yang memenuhi.'],
[String.raw`(x-1)^2<0`,[String.raw`\varnothing`,String.raw`\{1\}`,String.raw`(-\infty,1)\cup(1,\infty)`],0,'Tidak ada kuadrat real yang negatif. Pada akar kembar nilainya nol, bukan negatif.'],
[String.raw`x^2+1>0`,[String.raw`\varnothing`,String.raw`\{0\}`,String.raw`\mathbb R`],2,'Kuadrat tidak negatif, sehingga ditambah satu selalu positif. Tidak adanya akar real tidak menghalangi semua real menjadi solusi.'],
[String.raw`-(x^2+1)\ge0`,[String.raw`\mathbb R`,String.raw`\varnothing`,String.raw`\{0\}`],1,'Kuadrat ditambah satu selalu positif. Negatifnya selalu negatif sehingga tidak bisa lebih besar dari atau sama dengan nol.'],
[String.raw`x^2\le4`,[String.raw`\{-2,2\}`,String.raw`[-2,2]`,String.raw`(-\infty,-2]\cup[2,\infty)`],1,'Susun menjadi kuadrat dikurangi empat kurang dari atau sama dengan nol, lalu faktorkan. Solusinya seluruh daerah di antara akar, termasuk batasnya.']
];const solved=new Set();questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),num=document.createElement('span'),formula=document.createElement('span');num.dataset.noEquation='';num.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(num,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`quadratic-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#quadratic-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#quadratic-questions').append(box);});$('#quadratic-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#quadratic-reflection').value=localStorage.getItem('fondasi-quadratic-inequality-reflection')||'';}catch{$('#quadratic-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}$('#quadratic-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-quadratic-inequality-reflection',$('#quadratic-reflection').value);$('#quadratic-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#quadratic-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
